// Node 1 - UNIFIED ENTRY (runs after picker node 3). Normalizes condition -> booleans,
// sets condition/label, stages per-condition safety-netting, and builds the first-screen
// GUIDANCE text (the input dropdowns are NATIVE conditional form fields on node 11).
var LABEL={"smi":"smi","depression":"depression","adult_mh":"adult_mh","cyp":"cyp","risk":"risk","Severe Mental Illness Review":"smi","Adult Mental Health":"adult_mh","Depression Review":"depression","Children and Young People Mental Health and Learning Disability":"cyp","MH Risk Assessment":"risk"};
var LBL={"smi":"Severe Mental Illness Review","adult_mh":"Adult Mental Health","depression":"Depression Review","cyp":"Children and Young People Mental Health and Learning Disability","risk":"MH Risk Assessment"};
var SN={"smi": "<p style='box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px; color: rgb(54, 54, 54); font-family: \\\"Open Sans\\\"; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;'><span style=\\\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span style=\\\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></span></p><p style='box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px; color: rgb(54, 54, 54); font-family: \\\"Open Sans\\\"; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;' id=\\\"isPasted\\\"><span style=\\\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\">In an emergency, call 999 or go to A&amp;E.</span></p><p style='box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px; color: rgb(54, 54, 54); font-family: \\\"Open Sans\\\"; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;'><span style=\\\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span style=\\\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\\\">If you need urgent mental health support, you can call 111 and press 2 (available 24/7).</span></span></p><p><br></p>", "adult_mh": "<p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">In an emergency, call 999 or go to A&amp;E.</span></p><p><br></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></span></p><p><br></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span id=\\\"isPasted\\\">If you need urgent mental health support, you can call 111 and press 2 (available 24/7).</span></span></p>", "depression": "<p><span style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">There is no specific safety netting advice for this condition.</span></p><p><br></p><p id=\\\"isPasted\\\"><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></p><p><br></p>", "cyp": "<p id=\\\"isPasted\\\"><span style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\">Call 999 or go to A&amp;E immediately if you feel you may harm yourself or someone else</span></p><p><br></p><p><span id=\\\"isPasted\\\" style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\">Call 111 if you need urgent help for your mental health.&nbsp;</span></p><p><span style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\"><br></span></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></p><p><br></p>", "risk": "<p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">In an emergency, call 999 or go to A&amp;E.</span></p><p><br></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></span></p><p><br></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\"><span id=\\\"isPasted\\\">If you need urgent mental health support, you can call 111 and press 2 (available 24/7).</span></span></p>"};
var raw=ZT.getVariableValue("condition","").trim();
var key=LABEL[raw]||LABEL[raw.toLowerCase()]||"";

ZT.setFormData("risk_score",0);
ZT.setFormData("needs_picker", key==="");
ZT.setFormData("cond_smi", key==="smi");
ZT.setFormData("cond_adult_mh", key==="adult_mh");
ZT.setFormData("cond_depression", key==="depression");
ZT.setFormData("cond_cyp", key==="cyp");
ZT.setFormData("cond_risk", key==="risk");
if(key!==""){ ZT.setFormData("condition",key); ZT.setFormData("condition_label", LBL[key]||""); ZT.setTransformData("sn_html", SN[key]||""); }
var SMI_GUIDE="<p>Ask the patient about the following. Answer Yes/No for each, then press Continue.</p><p id=\"isPasted\"><span style=\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">This tree is for patients with known severe mental illness (e.g. psychosis, schizophrenia, bipolar affective disorder, patients on lithium treatment) who have been recalled for or want a review appointment</span></p><p><br></p><p><b>Does the patient have any emergency symptoms? Tick all that apply.</b></p><p id=\"isPasted\"><span style=\"color: rgb(0, 0, 0); font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\">If patient answers unsure / don&#39;t know to any of the symptoms below, please&nbsp;</span><strong><span style=\"color: rgb(0, 0, 0); font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\">tick</span></strong></p>";
var ADULT_GUIDE="<div><div class=\"zt-content-block zt-cb-type-script\"><div class=\"zt-cb-title\"><i class=\"zt-cb-icon\" contenteditable=\"false\"></i><h3>Script</h3></div><div class=\"zt-cb-body\"><p><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px;\" id=\"isPasted\"><em>\"Thank you for calling, I\u2019m here to help you.</em><em><span style=\"font-family: Tahoma, Geneva, sans-serif;\"><em>&nbsp;</em></span></em><em>Wo</em></span><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px;\"><em>uld you mind telling me how I can help? <span style=\"font-family: Tahoma, Geneva, sans-serif;\"><em>&nbsp;</em></span></em></span></p><p><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px;\"><em><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px;\"><em><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px;\"><em>Is this call for yourself or someone else?\"</em></span></em></span></em></span></p></div></div></div><h2 id=\"isPasted\"><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\">\ud83d\udcd6&nbsp;</span><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px;\"><strong>&nbsp;'IN CRI</strong><strong>SIS'</strong> is <u>our</u> shorthand for someone who feels that they are at risk of harming themselves (suicidal) or of harming others.&nbsp;</span></h2><ul><li style=\"list-style-type: none;\"><ul style=\"list-style-type: disc;\"><li style=\"font-style: italic;\"><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px;\"><em>Try <strong>not</strong> to use the word 'crisis' - instead, ask patients open-ended questions about what is concerning them (e.g., \"what thoughts are going through your mind regarding your (or someone else's) safety?\")</em></span></li><li style=\"font-style: italic;\"><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\"><em>At the bottom of every card in this tree, there is a 'Patient in crisis' button. &nbsp;If at any point in talking to the patient you feel that they are in crisis, you can just click this button to go directly to the MH Risk Assessment tree to assess them for more urgent care.</em></span></li></ul></li></ul><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"><br></p><h2><span style=\"color: rgb(184, 49, 47);\"><span style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 24px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; float: none; display: inline !important;\">\ud83d\ude36 If caller is <strong>reluctant to discuss</strong> the reason for the call \u27a1 <strong>select&nbsp;</strong><strong>button 3</strong> below.</span></span></h2><h2><span style=\"font-size: 24px; font-family: Tahoma, Geneva, sans-serif; color: rgb(184, 49, 47);\"><span style=\"font-family: Tahoma, Geneva, sans-serif; color: rgb(184, 49, 47);\" id=\"isPasted\">\ud83e\udec2&nbsp;</span>If calling to discuss the mental health of <strong>another patient:</strong></span></h2><div><ul><li style=\"list-style-type: none; font-size: 18px; color: rgb(184, 49, 47);\"><ul style=\"list-style-type: disc; font-size: initial; color: initial;\"><li style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px; color: rgb(184, 49, 47);\"><strong>DO NOT</strong> give information out - you can receive information on behalf of a patient, but NOT share information without a patient's expressed permission.</li><li style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px; color: rgb(184, 49, 47);\"><strong>Clarify</strong> the relationship between the caller and the patient.</li><li style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px; color: rgb(184, 49, 47);\"><strong>Hide</strong> consultation notes (so patient can't see).</li><li style=\"font-family: Tahoma, Geneva, sans-serif; font-size: 18px; color: rgb(184, 49, 47);\"><strong>Record</strong> the name of the caller and the organisation (if call coming from another agency).</li></ul></li></ul><p><br></p></div>";
var DEP_GUIDE="<p><span style=\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\">Examples of new symptoms:</span></p><ul><li><span style=\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\">suicidal thoughts</span></li><li><span style=\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\">self-harming</span></li></ul><p><span style=\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\"><br></span></p><p><i>The medication question applies when there are no new symptoms.</i></p>";
var g="";
if(key==="smi") g=SMI_GUIDE; else if(key==="adult_mh") g=ADULT_GUIDE; else if(key==="depression") g=DEP_GUIDE;
ZT.setTransformData("first_screen_html", g);

27.content:
// Eval-Adult: seen_before -> Any; else safety -> MHN(safe)/risk(unsafe).
function v(n){return ZT.getVariableValue(n,"").trim().toLowerCase();}
var risk=false;
if(v("seen_before")==="yes"){ZT.setFormData("outcome_key","adult_mh:any_seen");}
else if(v("safety_feeling")==="feeling safe"){ZT.setFormData("outcome_key","adult_mh:mhn_safe");}
else {risk=true;}
ZT.setFormData("adult_is_risk", risk);

55.content:
// Eval-CYP route: undiagnosed/worsening -> school route; else -> medication route.
function v(n){return ZT.getVariableValue(n,"").trim().toLowerCase();}
var school=(v("undiagnosed_condition")==="yes"||v("worsening_condition")==="yes");
ZT.setFormData("cyp_route", school?"school":"meds");

56.content:
// Combined CYP outcome setter (folds v6 node 128 school path + node 56 medication path).
// Sectioned by cyp_route (the variable that drove old router 49).
var route=ZT.getVariableValue("cyp_route","");
function v(n){return ZT.getVariableValue(n,"").trim().toLowerCase();}
if(route==="school"){ ZT.setFormData("outcome_key","cyp:gp"); }
else { if(v("start_medications")==="yes") ZT.setFormData("outcome_key","cyp:gp");
       else if(v("urgent_script")==="yes") ZT.setFormData("outcome_key","cyp:urgent_pharm");
       else ZT.setFormData("outcome_key","cyp:gp_accurx"); }

