// Node 88 - Shared outcome stager. Central catalog of all 21 outcomes.
// Upstream scripts/setters set outcome_key; this stages the shared Outcome screen (90).
var OUTCOMES = {
  "smi:mhn": {t:"Outcome: Mental Health Nurse", s:"1.MHNrt | 2.GPrtF2F", x:"Severe Mental Illness Review suggested outcome: \n1. MHN routine, F2F \n2. GP routine, double appointment F2F", h:"<h3>Outcome: Mental Health Nurse</h3><p><b>Suggested outcome:</b><br>Severe Mental Illness Review suggested outcome: <br>1. MHN routine, F2F <br>2. GP routine, double appointment F2F</p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"><span style=\"color: rgb(40, 50, 78); font-size: 24px;\">\ud83d\udcde <strong><span style=\"font-family: Tahoma,Geneva,sans-serif;\">CH Information</span></strong></span></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin-left: 40px;\" id=\"isPasted\"><span style=\"font-family: Tahoma, Geneva, sans-serif; color: rgb(40, 50, 78); font-size: 24px;\">Book this as a <strong>single</strong> appointment with MHN Nurse.</span></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin-left: 40px;\"><span style=\"font-family: Tahoma, Geneva, sans-serif; color: rgb(40, 50, 78); font-size: 24px;\">If the patient is reluctant, then book <strong>double</strong> <span style=\"font-family: Tahoma, Geneva, sans-serif; color: rgb(40, 50, 78); font-size: 24px;\" id=\"isPasted\">appointment&nbsp;</span>with GP.</span></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin-left: 40px;\"><span style=\"font-family: Tahoma, Geneva, sans-serif; color: rgb(40, 50, 78); font-size: 24px;\">This is a <strong>F2F</strong> appointment because patient has to have blood pressure done and is likely to need a blood test and/or a physical exam.</span></p><hr><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; w