xt-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"></p><p><a class=\"btn btn-success\" style=\"cursor:pointer;\" onclick=\"copy_to_clipboard();\"></a></p><p><br></p>"}
};
var key = ZT.getVariableValue("outcome_key", "");
var o = OUTCOMES[key] || {t:"",s:"",x:"",h:""};

// severity tone -> chip (class baked in JS so NO merge field ever sits in an HTML attribute)
var TONE = {
  "risk:emergency":"emergency", "cyp:emergency_out":"emergency",
  "cyp:paramedic":"urgent", "cyp:urgent_pharm":"urgent",
  "risk:oversight":"escalate", "risk:mhn_oversight":"escalate", "cyp:gp_decline":"escalate"
};
var CHIP = { emergency:"Emergency", urgent:"Urgent", escalate:"Escalate", routine:"Routine" };
var tone = TONE[key] || "routine";
ZT.setTransformData("chip_html", '<span class="pz-chip pz-chip-'+tone+'">'+CHIP[tone]+'</span>');

// clean title: "Outcome: Clinical Oversight" -> "Clinical Oversight"
ZT.setFormData("outcome_title_clean", (o.t||"").replace(/^Outcome:\s*/i,""));
ZT.setFormData("suggested_outcome_text", o.x);

// clinician notes = rich html minus duplicated title + "Suggested outcome" para,
// minus the empty legacy copy button, minus trailing blank paragraphs.
var notes = o.h || "";
notes = notes.replace(/^\s*<h3[^>]*>[\s\S]*?<\/h3>/i, "");
notes = notes.replace(/^\s*<p[^>]*>\s*<b>\s*Suggested outcome:?\s*<\/b>[\s\S]*?<\/p>/i, "");
notes = notes.replace(/<p>\s*<a[^>]*btn-success[^>]*>\s*<\/a>\s*<\/p>/gi, "");
notes = notes.replace(/(\s*<p[^>]*>\s*(<br\s*\/?>)?\s*<\/p>\s*)+$/i, "");
ZT.setTransformData("outcome_notes_html", notes.trim());

