// Node 210 - COMBINED FIRST-SCREEN EVAL. Folds v5 210 (SMI), 34 (Depression) and 40
// (CYP re-stage for callers phoning about a child). Reads the merged first screen's
// zt-data inputs, sets routing booleans + outcome_key. Router (node 13) only branches.
function v(n){return ZT.getVariableValue(n,"").trim().toLowerCase();}
function yes(n){return v(n)==="yes";}
var cond=ZT.getVariableValue("condition","");
ZT.setFormData("smi_is_risk",false);
ZT.setFormData("dep_go_postcard",false);
ZT.setFormData("adult_is_crisis",false);
ZT.setFormData("adult_is_child",false);
ZT.setFormData("adult_is_other",false);
if(cond==="smi"){
  var r=yes("feelsUnsafe")||yes("suicidal")||yes("harm");
  ZT.setFormData("smi_is_risk", r);
  if(!r) ZT.setFormData("outcome_key","smi:mhn");
} else if(cond==="depression"){
  var pc=yes("new_symptoms"); ZT.setFormData("dep_go_postcard", pc);
  if(!pc){ if(yes("about_medication")) ZT.setFormData("outcome_key","depression:pharmacist"); else ZT.setFormData("outcome_key","depression:mhn"); }
} else if(cond==="adult_mh"){
  var ct=v("caller_type");
  if(ct.indexOf("child")>=0){ ZT.setFormData("adult_is_child",true); ZT.setFormData("condition","cyp"); ZT.setFormData("condition_label","Children and Young People Mental Health and Learning Disability"); ZT.setTransformData("sn_html", "<p id=\\\"isPasted\\\"><span style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\">Call 999 or go to A&amp;E immediately if you feel you may harm yourself or someone else</span></p><p><br></p><p><span id=\\\"isPasted\\\" style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\">Call 111 if you need urgent help for your mental health.&nbsp;</span></p><p><span style=\\\"color: rgb(0, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\\\"><br></span></p><p><span style=\\\"font-size: 24px; color: rgb(0, 0, 0); font-family: Tahoma, Geneva, sans-serif;\\\" id=\\\"isPasted\\\">If your current symptoms worsen, you develop any new symptoms or have any other concerns, then please call back to the surgery. During the OOH period call 111.</span></p><p><br></p>"); }
  else if(ct.indexOf("routine")>=0 || ct.indexOf("not in crisis")>=0){ ZT.setFormData("adult_is_other",true); } else if(ct.indexOf("crisis")>=0){ ZT.setFormData("adult_is_crisis",true); }
  else { ZT.setFormData("adult_is_other",true); }
}

