// Eval-CYP non-verbal symptoms: not_moving -> Emergency; any other -> Paramedic; else continue.
function yes(n){return ZT.getVariableValue(n,"").trim().toLowerCase()==="yes";}
var cont=true;
if(yes("non_verbal")){
  if(yes("not_moving")){ZT.setFormData("outcome_key","cyp:emergency_out");cont=false;}
  else if(yes("ear_pulling")||yes("grunting")||yes("light_sensitivity")||yes("not_drinking_or_eating")){ZT.setFormData("outcome_key","cyp:paramedic");cont=false;}
}
ZT.setFormData("cyp_sym_continue", cont);

70.content:
// Eval-Risk: reproduce source risk_score (gated) then route.
// suicide any Yes=7; self-harm1 Yes=1 (+7 if self-harm2 Yes); harm1 Yes=1 (+1 if harm2 Yes).
function yes(n){return ZT.getVariableValue(n,"").trim().toLowerCase()==="yes";}
var s=0;
if(yes("risk_suicide_1")||yes("risk_suicide_2")) s+=7;
if(yes("risk_selfharm_1")){ s+=1; if(yes("risk_selfharm_2")) s+=7; }
if(yes("risk_harm_1")){ s+=1; if(yes("risk_harm_2")) s+=1; }
ZT.setFormData("risk_score", s);
var moderate=false;
if(s>=7) ZT.setFormData("outcome_key","risk:emergency");
else if(s===0) ZT.setFormData("outcome_key","risk:mhn_routine");
else moderate=true;
ZT.setFormData("risk_is_moderate", moderate);
